//! Single background owner of client state. No IO or wire parsing belongs in GPUI render.
use crate::{host::{DesktopHost,HostSnapshot,NodeIdentity,BackgroundAction,NodeMode},ui::*,views::forms::Editor};
use anyhow::{Result,Context,ensure};
use base64::Engine;
use sha2::{Digest,Sha256};
use serde_json::{Value,json};
use std::{collections::BTreeMap,path::PathBuf,sync::Arc,time::Duration};
use tokio::sync::{mpsc,watch};
use vibeface_client::{Client,ClientKey,Entry,Endpoint,ReadRequest,Action,DeliveryRead,MemoryBase,MemoryVersion,Provider,ProviderSettings};
use vibeface_protocol::workspace::{InputRequest,InputRoute,WorkspaceCommand,InputTarget,InputIntent,ScheduleAction};

#[derive(Clone)]pub enum HostAction{Refresh,Controller,Select(NodeIdentity),Start,Stop,Background(BackgroundAction),Remember(PathBuf),StartCandidate(crate::host::LocalNode),ClearSelection,Preferences(crate::host::Preferences)}
#[derive(Clone)]pub enum IdentityAction{Directory,Invite,Requests,Grant{device_id:String,manage:bool},Revoke(String),Rename{device_id:String,name:String},Recovery(bool),ConfirmJoin(String),GrantJoin{join_id:String,manage:bool},RejectJoin(String)}
#[derive(Clone)]pub enum Command{
 Refresh,Disconnect,Conversation(String),Save{editor:Editor,values:BTreeMap<String,String>,conversation_id:Option<String>},Input{conversation_id:String,draft:ComposerDraft},Workspace(WorkspaceCommand),StopReply(String),StopWork{conversation_id:String,work_id:String},Answer{conversation_id:String,question_id:String,text:String,action:Option<String>},Reconcile(String),DeleteBot(String),PrimaryBot(String),DeleteMemory{conversation_id:String,memory:Memory},Schedule{conversation_id:String,schedule_id:String,action:String},Identity(IdentityAction),Host(HostAction),DeliveryConfigure{enabled:bool,charity:bool,paid:bool},DeliveryConfirm(TransferOrder),DeliveryAccept(String),DeliveryReconcile(String),DeliverySave{order:TransferOrder,path:PathBuf},NodeSettings(String),ReadLogs{search:String},Transfers,Attachments{conversation_id:String,paths:Vec<PathBuf>},Shutdown,
}
pub enum Event{Snapshot(Arc<Snapshot>),Host(HostSnapshot),Notice(String),Error(String),Detail(Vec<(String,String)>),Attachments(Vec<vibeface_protocol::workspace::Attachment>),InputStored(String),ShutdownComplete}
pub struct Backend{host:DesktopHost,key:Option<Arc<ClientKey>>,client:Option<Client>,state:Snapshot,conversation:Option<String>,out:mpsc::Sender<Event>,snapshots:watch::Sender<Arc<Snapshot>>,attachments:Vec<vibeface_protocol::workspace::Attachment>}
impl Backend{
 pub fn spawn(host:DesktopHost,runtime:&tokio::runtime::Handle)->(mpsc::Sender<Command>,mpsc::Receiver<Event>,watch::Receiver<Arc<Snapshot>>,watch::Sender<bool>,tokio::task::JoinHandle<()>){
 let(tx,mut rx)=mpsc::channel(64);let(out,events)=mpsc::channel(64);let(snapshots,snapshot_rx)=watch::channel(Arc::new(Snapshot::default()));let(stop,mut stopping)=watch::channel(false);
 let task=runtime.spawn(async move{let mut backend=Self{host,key:None,client:None,state:Snapshot::default(),conversation:None,out,snapshots,attachments:vec![]};backend.publish_host().await;let mut timer=tokio::time::interval(Duration::from_secs(5));
 'commands:loop{tokio::select!{biased;_=stopping.changed()=>break,
 command=rx.recv()=>{let Some(command)=command else{break};if matches!(command,Command::Shutdown){break}let result=tokio::select!{biased;_=stopping.changed()=>break 'commands,result=backend.run(command)=>result};if let Err(error)=result{let _=backend.out.send(Event::Error(format!("操作未完成：{error}"))).await;}},
 _=timer.tick(),if backend.client.is_some()=>{let result=tokio::select!{biased;_=stopping.changed()=>break 'commands,result=backend.refresh()=>result};if let Err(error)=result{backend.state.online=false;backend.state.status="连接中断，显示最近记录。结果未知的操作须先核对。".into();backend.state.error=Some(error.to_string());backend.publish();}}}}
 match backend.host.shutdown().await{Ok(())=>{let _=backend.out.send(Event::ShutdownComplete).await;},Err(error)=>{let _=backend.out.send(Event::Error(format!("Node 未能正常停止：{error}"))).await;}}
 });(tx,events,snapshot_rx,stop,task)}

 fn publish(&self){self.snapshots.send_replace(Arc::new(self.state.clone()));}
 async fn publish_host(&self){let _=self.out.send(Event::Host(self.host.snapshot())).await;}
 fn client(&self)->Result<&Client>{self.client.as_ref().context("请先连接个人网络")}
 async fn submit(&mut self,action:Action)->Result<()>{let saved_input=if let Action::Input{input,..}=&action{Some(input.text.clone())}else{None};let delivery=matches!(&action,Action::Delivery(_));let operation=self.client()?.submit(action).await?;if let Some(text)=saved_input{let _=self.out.send(Event::InputStored(text)).await;}let _=self.out.send(Event::Notice(format!("操作 {}：{:?}。已接收不代表执行完成。",operation.id,operation.state))).await;self.refresh().await?;if delivery{self.refresh_delivery().await?;}Ok(())}
 async fn refresh(&mut self)->Result<()>{let client=self.client()?.clone();let home=client.read(ReadRequest::Home).await?;let nodes=client.read(ReadRequest::Nodes).await?;let workspace=client.read(ReadRequest::Workspace).await?;
 let mut next=self.state.clone();next.bots=decode_list(&home,"bots")?;next.nodes=decode_list(&nodes,"nodes")?;next.tasks=decode_list(&workspace,"tasks")?;next.channels=decode_list(&workspace,"channels")?;next.inputs=decode_list(&workspace,"inputs")?;
 if let Some(id)=&self.conversation{next.conversation=serde_json::from_value(client.read(ReadRequest::Conversation{conversation_id:id.clone()}).await?).context("对话响应格式无效")?;}
 next.pending=client.pending().await?.into_iter().map(|p|Pending{id:p.id,state:format!("{:?}",p.state)}).collect();next.online=true;next.synced=true;next.status="已读取当前连接。未确认的操作保留在待处理列表。".into();next.error=None;self.state=next;self.publish();Ok(())}
 async fn connect(&mut self,key:Arc<ClientKey>,entry:Entry,local:bool)->Result<()>{self.state.generation+=1;self.state.synced=false;self.state.online=false;self.state.bots.clear();self.state.conversation=Conversation::default();self.state.network=key.network_id().map(str::to_owned);self.state.client_id=Some(key.device_id().into());self.publish();let client=Client::open(key.clone(),if local{Endpoint::Local(entry)}else{Endpoint::Gateway(entry)},self.host.client_storage_dir().join("outbox")).await?;self.key=Some(key);self.client=Some(client);self.identity(IdentityAction::Directory).await?;self.refresh().await}
 async fn identity(&mut self,action:IdentityAction)->Result<()>{let key=self.key.as_ref().context("本机身份尚未解锁")?.clone();let mut session=key.connect(None).await?;match action{
 IdentityAction::Directory=>{let directory=session.directory().await?;let members=serde_json::to_value(directory.view.members)?;self.state.members=serde_json::from_value(members)?;self.state.can_manage=self.state.members.iter().any(|m|m.device_id==key.device_id()&&m.manage);self.publish();},
 IdentityAction::Invite=>{let link=session.invite().await?;let _=self.out.send(Event::Detail(vec![("邀请链接，请只交给本人设备".into(),link)])).await;},
 IdentityAction::Requests=>{self.state.joins=serde_json::from_value(serde_json::to_value(session.requests().await?)?)?;self.publish();},
 IdentityAction::Rename{device_id,name}=>{session.grant(&device_id,Some(&name),None).await?;},IdentityAction::Grant{device_id,manage}=>{session.grant(&device_id,None,Some(manage)).await?;},IdentityAction::Revoke(id)=>{session.revoke(&id).await?;},IdentityAction::Recovery(approve)=>{session.settle_recovery(approve).await?;},IdentityAction::ConfirmJoin(id)=>{session.confirm_join(&id).await?;},IdentityAction::GrantJoin{join_id,manage}=>{session.grant_join(&join_id,manage).await?;},IdentityAction::RejectJoin(id)=>{session.reject_join(&id).await?;}}
 Ok(())}
 async fn run(&mut self,command:Command)->Result<()>{match command{
 Command::Refresh=>{if self.client.is_some(){self.refresh().await?;}},Command::Disconnect=>{self.client=None;self.key=None;self.state=Snapshot{generation:self.state.generation+1,status:"已断开。个人网络数据和 Node 保持原样。".into(),..Default::default()};self.publish();},
 Command::Conversation(id)=>{self.conversation=Some(id);self.refresh().await?;},Command::Save{editor,values,conversation_id}=>self.save(editor,values,conversation_id).await?,
 Command::Input{conversation_id,draft}=>{draft.validate().map_err(anyhow::Error::msg)?;let sequence=self.client()?.next_input_sequence(&conversation_id,&draft.target).await?;let attachments=draft.attachments;self.attachments.clear();self.submit(Action::Input{conversation_id,input:InputRequest{message_id:uuid::Uuid::new_v4().to_string(),route:InputRoute{target:draft.target,intent:draft.intent,sequence,expected_revision:draft.expected_revision},text:draft.text,attachments,report_results:None}}).await?;},
 Command::Workspace(command)=>self.submit(Action::Workspace{command}).await?,Command::StopWork{conversation_id,work_id}=>self.submit(Action::StopWork{conversation_id,work_id}).await?,
 Command::StopReply(conversation_id)=>{let triggers=self.state.conversation.scheduler.jobs.iter().filter(|j|!["completed","cancelled","failed"].contains(&j.state.as_str())).map(|j|j.trigger.clone()).collect::<Vec<_>>();ensure!(!triggers.is_empty(),"没有已确认的活动回复可停止");for trigger in triggers{self.submit(Action::StopReply{conversation_id:conversation_id.clone(),trigger}).await?;}},
 Command::Answer{conversation_id,question_id,text,..}=>self.submit(Action::Answer{conversation_id,question_id,text}).await?,Command::Reconcile(id)=>{let result=self.client()?.reconcile(&id).await?;let _=self.out.send(Event::Notice(format!("操作回执：{:?}",result.state))).await;self.refresh().await?;},
 Command::DeleteBot(conversation_id)=>self.submit(Action::DeleteBot{conversation_id}).await?,Command::PrimaryBot(conversation_id)=>self.submit(Action::SetPrimaryBot{conversation_id}).await?,
 Command::DeleteMemory{conversation_id,memory}=>self.submit(Action::Memory{conversation_id,memory_id:memory.memory_id,base:memory_base(&memory.metadata)?,after:None}).await?,
 Command::Schedule{conversation_id,schedule_id,action}=>{let action=match action.as_str(){"pause"=>ScheduleAction::Pause,"resume"=>ScheduleAction::Resume,"delete"=>ScheduleAction::Delete,_=>anyhow::bail!("未知计划动作")};self.submit(Action::Schedule{conversation_id,schedule_id,action}).await?;},
 Command::Identity(action)=>{let refresh=!matches!(&action,IdentityAction::Directory|IdentityAction::Requests);self.identity(action).await?;if refresh{self.identity(IdentityAction::Directory).await?;self.identity(IdentityAction::Requests).await?;}},Command::Host(action)=>{match action{HostAction::Refresh=>{self.host.discover().await?;},HostAction::Controller=>self.host.choose_mode(NodeMode::Controller)?,HostAction::Select(identity)=>{self.host.select_node(&identity).await?;},HostAction::Start=>{self.host.start_owned().await?;},HostAction::Stop=>self.host.stop_owned().await?,HostAction::Background(action)=>{self.host.background(action).await?;},HostAction::Remember(path)=>{self.host.remember_directory(path).await?;},HostAction::StartCandidate(node)=>{self.host.start_candidate(&node).await?;},HostAction::ClearSelection=>self.host.clear_selection()?,HostAction::Preferences(preferences)=>self.host.save_preferences(preferences)?,}self.publish_host().await;},
 Command::NodeSettings(_)=>{let value=self.client()?.read(ReadRequest::NodeSettings).await?;let _=self.out.send(Event::Detail(settings_rows(&value))).await;},Command::ReadLogs{search}=>{let value=self.client()?.read(ReadRequest::Logs).await?;let rows=value["entries"].as_array().map(|items|items.iter().filter_map(|entry|{let message=entry["message"].as_str()?;if !search.is_empty()&&!message.contains(&search){return None}Some((entry["level"].as_str().unwrap_or("info").into(),message.into()))}).collect()).unwrap_or_default();let _=self.out.send(Event::Detail(rows)).await;},
 Command::Transfers=>self.refresh_delivery().await?,
 Command::DeliveryConfigure{enabled,charity,paid}=>self.submit(Action::Delivery(vibeface_client::DeliveryAction::Configure{enabled,charity_enabled:charity,paid_enabled:paid})).await?,
 Command::DeliveryConfirm(order)=>{ensure!(order.phase=="prepared"&&order.role=="sender","先查询原订单，当前订单不可确认");let current=self.client()?.read(ReadRequest::Delivery(DeliveryRead::Get{order_id:order.order_id.clone()})).await?;let current:TransferOrder=serde_json::from_value(current)?;ensure!(same_terms(&order,&current),"订单条款已变化，未确认付款");self.submit(Action::Delivery(vibeface_client::DeliveryAction::Confirm{intent_id:order.intent_id})).await?;},
 Command::DeliveryAccept(order_id)=>self.submit(Action::Delivery(vibeface_client::DeliveryAction::Accept{order_id})).await?,
 Command::DeliveryReconcile(order_id)=>self.submit(Action::Delivery(vibeface_client::DeliveryAction::Reconcile{order_id})).await?,
 Command::DeliverySave{order,path}=>{let value=self.client()?.read(ReadRequest::Delivery(DeliveryRead::Read{order_id:order.order_id.clone()})).await?;let encoded=value["content_base64"].as_str().context("文件响应缺少内容")?;let bytes=base64::engine::general_purpose::STANDARD.decode(encoded)?;ensure!(bytes.len()as u64==order.bytes&&format!("{:x}",Sha256::digest(&bytes))==order.sha256,"文件大小或 SHA-256 不匹配，未保存");match crate::host::platform::save_selected(Some(path),&bytes)?{crate::host::platform::SaveResult::Saved(_)=>{let _=self.out.send(Event::Notice("文件已保存。".into())).await;},crate::host::platform::SaveResult::Cancelled=>{}}},
 Command::Attachments{conversation_id:_,paths}=>{let client=self.client()?.clone();let mut attachments=vec![];for path in paths{let name=path.file_name().context("附件文件名无效")?.to_string_lossy().into_owned();let metadata=tokio::fs::metadata(&path).await?;ensure!(metadata.len()<=64*1024*1024,"附件超过 64 MiB");let bytes=tokio::fs::read(&path).await?;attachments.push(client.store_attachment(name,bytes).await?);}self.attachments=attachments.clone();let _=self.out.send(Event::Attachments(attachments)).await;},Command::Shutdown=>{},}Ok(())}
 async fn refresh_delivery(&mut self)->Result<()>{let client=self.client()?;let status=client.read(ReadRequest::Delivery(DeliveryRead::Status)).await?;let list=client.read(ReadRequest::Delivery(DeliveryRead::List)).await?;let mut delivery:Delivery=serde_json::from_value(status)?;delivery.orders=decode_list(&list,"orders")?;self.state.delivery=delivery;self.publish();Ok(())}
 async fn delivery_intent(&self,terms:Value)->Result<String>{let client=self.client()?;let path=self.host.client_storage_dir().join("delivery-intents.json");let fingerprint=format!("{:x}",Sha256::digest(serde_json::to_vec(&json!({"network":client.network_id(),"client":client.client_id(),"target":self.key.as_ref().and_then(|k|k.entry()).map(|e|e.node_id.as_str()),"terms":terms}))?));let read_path=path.clone();let mut entries:BTreeMap<String,String>=tokio::task::spawn_blocking(move||->Result<_>{if !read_path.try_exists()?{return Ok(BTreeMap::new())}let bytes=vibeface_bridge::platform::privatefs::read_private_bounded(&read_path,4*1024*1024,"文件传输意图")?;Ok(serde_json::from_slice(&bytes)?)}).await??;if let Some(id)=entries.get(&fingerprint){return Ok(id.clone())}let intent=uuid::Uuid::new_v4().to_string();entries.insert(fingerprint,intent.clone());tokio::task::spawn_blocking(move||vibeface_bridge::platform::privatefs::write_atomic(&path,&serde_json::to_vec(&entries)?)).await??;Ok(intent)}
 async fn save(&mut self,editor:Editor,values:BTreeMap<String,String>,conversation_id:Option<String>)->Result<()>{let get=|key:&str|values.get(key).cloned().unwrap_or_default();let id=||conversation_id.clone().context("请先打开一个 Bot 的对话");let entry=||Entry{origin:get("origin"),node_id:get("node_id")};let new_id=||uuid::Uuid::new_v4().to_string();let csv=|key:&str|get(key).split(',').map(str::trim).filter(|s|!s.is_empty()).map(str::to_owned).collect::<Vec<_>>();match editor{
 Editor::ConnectLocal=>{let directory=self.host.client_storage_dir();let passphrase=get("passphrase");let key=ClientKey::open(&directory,&passphrase)?;let identity=self.host.snapshot().selected.context("请先明确选择运行中的本机 Node")?;let credential=self.host.local_credential(&identity).await?;self.connect(Arc::new(key),Entry{origin:credential.origin,node_id:credential.node_id},true).await?;},
 Editor::Connect=>{let directory=self.host.client_storage_dir();let passphrase=get("passphrase");let key=if ClientKey::exists(&directory){ClientKey::open(&directory,&passphrase)?}else{ClientKey::create(&directory,&passphrase)?};let target=if get("origin").is_empty(){key.entry().cloned().context("请输入 Gateway 地址和目标 Node 公钥")?}else{entry()};self.connect(Arc::new(key),target,false).await?;},
 Editor::Join=>{let directory=self.host.client_storage_dir();let passphrase=get("passphrase");let mut key=if ClientKey::exists(&directory){ClientKey::open(&directory,&passphrase)?}else{ClientKey::create(&directory,&passphrase)?};let mut enrollment=vibeface_client::Enrollment::start(&key,&get("origin"),&get("ticket"),&get("name")).await?;let deadline=tokio::time::Instant::now()+Duration::from_secs(600);loop{ensure!(tokio::time::Instant::now()<deadline,"邀请已过期，请重新申请");match enrollment.poll().await?{vibeface_client::Progress::Waiting=>{},vibeface_client::Progress::Code(code)=>{let _=self.out.send(Event::Notice(format!("请在管理设备核对短码：{code}"))).await;},vibeface_client::Progress::Joined=>break}tokio::time::sleep(Duration::from_secs(1)).await;}let(network,entry)=enrollment.finish()?;key.remember(&network,entry.clone())?;self.connect(Arc::new(key),entry,false).await?;},
 Editor::Recovery=>{let directory=self.host.client_storage_dir();let passphrase=get("passphrase");let mut key=if ClientKey::exists(&directory){ClientKey::open(&directory,&passphrase)?}else{ClientKey::create(&directory,&passphrase)?};let result=vibeface_client::recover(&mut key,entry(),&PathBuf::from(get("old_file")),&get("password"),&PathBuf::from(get("new_file")),&get("name"),None).await?;let _=result;let _=self.out.send(Event::Notice("恢复请求已提交。请保管新恢复文件，等待管理设备批准或恢复等待期结束。".into())).await;},
 Editor::CreateBot=>{ensure!(!get("name").trim().is_empty(),"请输入 Bot 名称");let project=if get("cwd").is_empty(){None}else{Some(vibeface_client::BotProject{target_node:get("target_node"),cwd:get("cwd")})};let scheduler_node=self.key.as_ref().and_then(|k|k.entry()).context("当前 Node 未确认")?.node_id.clone();self.submit(Action::CreateBot{bot_id:new_id(),conversation_id:new_id(),name:get("name"),instructions:get("instructions"),scheduler_node,project}).await?;},
 Editor::EditBot=>{let conversation_id=id()?;let bot=self.state.bots.iter().find(|b|b.conversation_id==conversation_id).context("Bot 未加载")?;let bot_id=bot.bot_id.clone();let instruction=format!("请更新你的配置：名称 {}；指令 {}；Provider {}；模型 {}；推理强度 {}。",get("name"),get("instructions"),get("provider"),get("model"),get("effort"));let project=if get("cwd").is_empty(){None}else{Some(vibeface_client::BotProject{target_node:get("target_node"),cwd:get("cwd")})};self.submit(Action::SetBotProject{conversation_id:conversation_id.clone(),project}).await?;self.input_instruction(conversation_id,bot_id,instruction).await?;},
 Editor::CreateTask=>self.submit(Action::Workspace{command:WorkspaceCommand::CreateTask{task_id:new_id(),channel_id:None,parent_task_id:None,owner_bot:get("owner_bot"),title:get("title"),request:get("request"),expected_result:get("expected_result"),source_events:vec![],dependencies:csv("dependencies"),reply_only:false}}).await?,
 Editor::EditTask(task_id,expected_revision)=>self.submit(Action::Workspace{command:WorkspaceCommand::ReviseTask{task_id,expected_revision,request:get("request"),expected_result:get("expected_result"),dependencies:csv("dependencies")}}).await?,
 Editor::Member(device_id)=>{self.identity(IdentityAction::Rename{device_id,name:get("name")}).await?;self.identity(IdentityAction::Directory).await?;},
 Editor::ChannelPost(channel_id)=>self.submit(Action::Workspace{command:WorkspaceCommand::PostChannelMessage{channel_id,message_id:new_id(),text:get("text"),attachments:vec![],recipient_bot:(!get("recipient_bot").is_empty()).then(||get("recipient_bot")),task_id:(!get("task_id").is_empty()).then(||get("task_id")),reply_to:(!get("reply_to").is_empty()).then(||get("reply_to"))}}).await?,
 Editor::CreateChannel=>self.submit(Action::Workspace{command:WorkspaceCommand::CreateChannel{channel_id:new_id(),title:get("title"),purpose:get("purpose"),members:csv("members"),coordinator_bot:get("coordinator_bot"),coordinator_node:get("coordinator_node")}}).await?,
 Editor::EditChannel(channel_id,expected_revision,owner_epoch)=>self.submit(Action::Workspace{command:WorkspaceCommand::ConfigureChannel{channel_id,expected_revision,owner_epoch,title:get("title"),purpose:get("purpose"),members:csv("members"),coordinator_bot:get("coordinator_bot"),coordinator_node:get("coordinator_node")}}).await?,
 Editor::Memory(memory)=>{let(memory_id,base)=if let Some(memory)=memory{(memory.memory_id,memory_base(&memory.metadata)?)}else{(new_id(),MemoryBase{epoch:1,version:None})};self.submit(Action::Memory{conversation_id:id()?,memory_id,base,after:Some(get("text"))}).await?;},
 Editor::Schedule=>{let conversation_id=id()?;let bot_id=self.state.bots.iter().find(|b|b.conversation_id==conversation_id).context("Bot 未加载")?.bot_id.clone();let time=get("first_run_at_ms").parse::<i64>().context("首次执行时间须为 Unix 毫秒")?;let interval=get("every_minutes");if !interval.is_empty(){ensure!(interval.parse::<u64>()?>0,"间隔分钟须大于零");}let instruction=format!("请创建计划：名称 {}；指令 {}；首次执行时间 Unix 毫秒 {}；间隔分钟 {}。",get("name"),get("prompt"),time,if interval.is_empty(){"仅执行一次"}else{&interval});self.input_instruction(conversation_id,bot_id,instruction).await?;},
 Editor::Answer(question_id)=>self.submit(Action::Answer{conversation_id:id()?,question_id,text:get("text")}).await?,
 Editor::Logs=>{let value=self.client()?.read(ReadRequest::Logs).await?;let search=get("search");let level=get("level");let source=get("source");let rows=value["entries"].as_array().map(|rows|rows.iter().filter_map(|entry|{let text=entry["message"].as_str()?;if !text.contains(&search)||!level.is_empty()&&entry["level"]!=level||!source.is_empty()&&entry["source"]!=source{return None}Some((entry["level"].as_str().unwrap_or("info").into(),text.into()))}).collect()).unwrap_or_default();let _=self.out.send(Event::Detail(rows)).await;},
 Editor::Avatar=>{let conversation_id=id()?;let hue=get("hue").parse::<u16>()?;ensure!(hue<360,"色相须在 0 到 359 之间");self.submit(Action::SetBotAvatar{conversation_id,version:None,avatar:Some(vibeface_client::Avatar{outline:serde_json::from_value(json!(get("outline")))?,eyes:serde_json::from_value(json!(get("eyes")))?,hue})}).await?;},
 Editor::NodeSettings=>{let raw=self.client()?.read(ReadRequest::NodeSettings).await?;let backup=raw["settings"]["manager"]["backup"].clone();let manager=if get("provider").is_empty(){None}else{Some(vibeface_client::ManagerSettings{provider:serde_json::from_value(json!(get("provider")))?,workspace:get("workspace").into(),model:get("model"),reasoning_effort:(!get("reasoning_effort").is_empty()).then(||get("reasoning_effort")),backup:if backup.is_null(){vibeface_client::BackupPolicy::default()}else{serde_json::from_value(backup)?}})};self.submit(Action::NodeSettings(vibeface_client::NodeSettings{roots:get("roots").lines().map(PathBuf::from).collect(),manager})).await?;},
 Editor::Triage=>{let projects=get("projects").lines().filter(|line|!line.trim().is_empty()).map(|line|{let(prefix,outlet)=line.split_once('=').context("项目规则须写为 prefix=record 或 prefix=both")?;Ok(vibeface_client::ProjectOutlet{prefix:prefix.trim().into(),outlet:serde_json::from_value(json!(outlet.trim()))?})}).collect::<Result<Vec<_>>>()?;self.submit(Action::Triage(vibeface_client::TriageSettings{default_outlet:serde_json::from_value(json!(get("default_outlet")))?,projects,webhook_url:(!get("webhook_url").is_empty()).then(||get("webhook_url")),scan_codex_sessions:get("scan_codex_sessions")=="true",codex_sessions:(!get("codex_sessions").is_empty()).then(||get("codex_sessions").into()),webhook_secret:if get("webhook_secret").is_empty(){vibeface_client::SecretChange::Keep}else{vibeface_client::SecretChange::Set(get("webhook_secret"))}})).await?;},
 Editor::Provider=>{let provider:Provider=serde_json::from_value(json!(get("provider")))?;self.submit(Action::ProviderSettings(ProviderSettings{provider,bot:parse_optional_bool(&get("bot"))?,execution:parse_optional_bool(&get("execution"))?,execution_model:Some(get("model")),bin:if get("bin").is_empty(){None}else{Some(get("bin").into())},connect_local:get("connect_local")=="true",app_server:if get("app_server_mode").is_empty(){None}else{Some(vibeface_client::AppServer{mode:serde_json::from_value(json!(get("app_server_mode")))?,socket:(!get("socket").is_empty()).then(||PathBuf::from(get("socket")))})},env:get("env").lines().map(|line|{let(key,value)=line.split_once('=').context("环境变量须写为 NAME=value")?;ensure!(!key.trim().is_empty(),"环境变量名称为空");Ok((key.trim().to_owned(),Some(value.to_owned())))}).collect::<Result<BTreeMap<_,_>>>()?})).await?;},
 Editor::Relay=>self.submit(Action::Relay{volunteer:get("volunteer")=="true",listen:(!get("listen").is_empty()).then(||get("listen")),url:(!get("url").is_empty()).then(||get("url")),rate:if get("rate").is_empty(){None}else{Some(get("rate").parse()?)},max_clients:if get("max_clients").is_empty(){None}else{Some(get("max_clients").parse()?)},max_clients_per_ip:if get("max_clients_per_ip").is_empty(){None}else{Some(get("max_clients_per_ip").parse()?)}}).await?,
 Editor::Transfer=>{ensure!(self.state.can_manage,"仅管理设备可准备订单");let path=PathBuf::from(get("file"));let metadata=tokio::fs::metadata(&path).await?;ensure!(self.state.delivery.enabled&&metadata.len()<=self.state.delivery.max_file_bytes,"传输未开启或文件超过允许大小");let name=path.file_name().context("文件名无效")?.to_string_lossy().into_owned();let content=tokio::fs::read(&path).await?;ensure!(content.len()as u64==metadata.len(),"文件读取过程中大小改变");let mode: vibeface_client::DeliveryMode=serde_json::from_value(json!(get("mode")))?;let acceptance:vibeface_client::DeliveryAcceptance=serde_json::from_value(json!(get("acceptance")))?;let intent_id=self.delivery_intent(json!({"receiver":get("receiver_peer"),"provider":get("provider_peer"),"mode":get("mode"),"acceptance":get("acceptance"),"name":name,"bytes":content.len(),"sha256":format!("{:x}",Sha256::digest(&content)),"service_cap":get("max_service_amount"),"gas_cap":get("max_gas_amount")})).await?;self.submit(Action::Delivery(vibeface_client::DeliveryAction::Prepare(vibeface_client::DeliveryPrepare{intent_id,receiver_peer:get("receiver_peer"),provider_peer:get("provider_peer"),mode,acceptance,name,content_base64:base64::engine::general_purpose::STANDARD.encode(content),max_service_amount:get("max_service_amount"),max_gas_amount:get("max_gas_amount")}))).await?;},
 }Ok(())}
 async fn input_instruction(&mut self,conversation_id:String,bot_id:String,text:String)->Result<()>{let target=InputTarget::BotMain{bot_id};let sequence=self.client()?.next_input_sequence(&conversation_id,&target).await?;self.submit(Action::Input{conversation_id,input:InputRequest{message_id:uuid::Uuid::new_v4().to_string(),route:InputRoute{target,intent:InputIntent::Continue,sequence,expected_revision:None},text,attachments:vec![],report_results:None}}).await}
}
fn memory_base(metadata:&MemoryMetadata)->Result<MemoryBase>{Ok(MemoryBase{epoch:metadata.epoch.try_into()?,version:Some(MemoryVersion{revision:metadata.revision.clone(),control_revision:metadata.control_revision.try_into()?,source_event_hash:metadata.source_event_hash.clone()})})}
fn settings_rows(value:&Value)->Vec<(String,String)>{let mut rows=vec![];if let Some(providers)=value["providers"].as_array(){for provider in providers{rows.push((provider["provider"].as_str().unwrap_or("Provider").into(),format!("{} · {}",provider["state"].as_str().unwrap_or("状态未知"),provider["readiness"]["state"].as_str().unwrap_or("尚未探测"))));}}rows}

fn same_terms(a:&TransferOrder,b:&TransferOrder)->bool{a.order_id==b.order_id&&a.intent_id==b.intent_id&&a.mode==b.mode&&a.acceptance==b.acceptance&&a.source_peer==b.source_peer&&a.receiver_peer==b.receiver_peer&&a.provider_peer==b.provider_peer&&a.name==b.name&&a.bytes==b.bytes&&a.sha256==b.sha256&&a.payment.total==b.payment.total&&a.payment.gas_cap==b.payment.gas_cap&&a.payment.payer==b.payment.payer&&a.payment.provider_wallet==b.payment.provider_wallet}

fn parse_optional_bool(value:&str)->Result<Option<bool>>{match value{""=>Ok(None),"true"=>Ok(Some(true)),"false"=>Ok(Some(false)),_=>anyhow::bail!("请输入 true 或 false")}}
